"""Private AOF7.2 generation/restore; source helpers remain unchanged."""
import shutil,time
from pathlib import Path
from redis_native import NativeRedis


class AOFRedis(NativeRedis):
    def __init__(self,restore=None):self.restore=restore
    def start(self):
        if not getattr(self,'configured',False):
            with self.config.open('a',encoding='utf8') as stream:
                stream.write('\nappendonly yes\nappendfsync always\nappenddirname appendonlydir\nappendfilename appendonly.aof\n')
            if self.restore is not None:shutil.copytree(self.restore,self.root/'appendonlydir')
            self.configured=True
        super().start()


def info(command,section):
    return dict(line.split(':',1) for line in command('INFO',section).splitlines() if ':' in line)


def await_aof(command,deadline=4):
    end=time.monotonic()+deadline
    while time.monotonic()<end:
        status=info(command,'persistence')
        if status.get('aof_enabled')=='1' and status.get('aof_rewrite_in_progress')=='0' and status.get('aof_rewrite_scheduled')=='0' and status.get('aof_last_write_status')=='ok':return status
        time.sleep(.01)
    raise RuntimeError('NATIVE_ENVIRONMENT_ERROR: private AOF did not become ready')
